<?php
declare(strict_types=1);

require __DIR__.'/bootstrap.php';
require tamiran_private_root().'/v2-core.php';

function inventory_v2_payload(PDO $pdo,array $scope):array
{
    $statement=$pdo->prepare('SELECT i.id,i.public_id,i.item_code,i.title,i.category,i.unit_title,i.purchase_price,i.sale_price,i.minimum_quantity,i.hot_return_required,i.hot_evidence_rules_json,s.warehouse_id,s.physical_quantity,s.reserved_quantity,(s.physical_quantity-s.reserved_quantity) AS available_quantity,s.average_unit_cost,s.row_version FROM repair_inventory_items i INNER JOIN repair_branch_stock s ON s.item_id=i.id AND s.shop_id=i.shop_id WHERE i.shop_id=:shop AND s.branch_id=:branch AND i.is_active=1 ORDER BY i.title LIMIT 1000');
    $statement->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$items=$statement->fetchAll();
    foreach($items as &$item){$item['id']=(int)$item['id'];foreach(['purchase_price','sale_price','minimum_quantity','physical_quantity','reserved_quantity','available_quantity','average_unit_cost','row_version']as$key)$item[$key]=(int)$item[$key];$item['hot_return_required']=(bool)$item['hot_return_required'];if(!in_array($scope['role'],['repair_manager','finance_cashier','warehouse_keeper'],true)){unset($item['purchase_price'],$item['average_unit_cost']);}}
    unset($item);
    $requestWhere='r.shop_id=:shop AND r.branch_id=:branch';$params=['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']];
    if($scope['role']==='technician'){$requestWhere.=' AND r.requested_by_user_id=:actor';$params['actor']=$scope['actor']['id'];}
    $requests=$pdo->prepare("SELECT r.*,CASE WHEN r.reservation_expires_at IS NOT NULL AND r.reservation_expires_at<NOW() AND r.status IN ('reserved','partially_delivered') THEN 1 ELSE 0 END AS reservation_is_expired,i.item_code,i.title AS item_title,c.receipt_number,u.display_name AS requester_name FROM repair_part_requests r LEFT JOIN repair_inventory_items i ON i.id=r.item_id INNER JOIN repair_cases c ON c.id=r.case_id INNER JOIN tamiran_users u ON u.id=r.requested_by_user_id WHERE {$requestWhere} ORDER BY r.updated_at DESC LIMIT 1000");$requests->execute($params);
    $rows=$requests->fetchAll();foreach($rows as &$row){foreach(['id','case_id','item_id','quantity','reserved_quantity','delivered_quantity','consumed_quantity','returned_quantity']as$key)$row[$key]=$row[$key]===null?null:(int)$row[$key];$row['reservation_is_expired']=(bool)$row['reservation_is_expired'];}unset($row);
    $issueWhere='x.shop_id=:shop AND x.branch_id=:branch';$issueParams=['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']];if($scope['role']==='technician'){$issueWhere.=' AND x.technician_user_id=:issue_actor';$issueParams['issue_actor']=$scope['actor']['id'];}
    $issues=$pdo->prepare("SELECT x.id,x.public_id,x.part_request_id,x.case_id,x.item_id,x.technician_user_id,x.quantity,x.status,x.notes,x.created_at,c.receipt_number,i.item_code,i.title AS item_title,u.display_name AS technician_name FROM repair_part_issues x INNER JOIN repair_cases c ON c.id=x.case_id INNER JOIN repair_inventory_items i ON i.id=x.item_id INNER JOIN tamiran_users u ON u.id=x.technician_user_id WHERE {$issueWhere} ORDER BY x.created_at DESC LIMIT 1000");$issues->execute($issueParams);$issueRows=$issues->fetchAll();foreach($issueRows as &$issue){foreach(['id','part_request_id','case_id','item_id','technician_user_id','quantity']as$key)$issue[$key]=(int)$issue[$key];}unset($issue);
    $warehouse=$pdo->prepare('SELECT id,public_id,title FROM repair_warehouses WHERE shop_id=:shop AND branch_id=:branch AND is_main=1 AND is_active=1 LIMIT 1');$warehouse->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);
    return ['items'=>$items,'requests'=>$rows,'issues'=>$issueRows,'warehouse'=>$warehouse->fetch()?:null];
}

function inventory_v2_request(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'part.request',['technician'],'ثبت درخواست قطعه مجاز نیست.');$caseId=(int)($input['caseId']??0);$itemId=(int)($input['itemId']??0);$quantity=(int)($input['quantity']??0);if($quantity<1||$quantity>100000)throw new TamiranApiException('تعداد درخواست معتبر نیست.');
    $case=v2_case($pdo,$scope,$caseId);if($case['locked_at']!==null)throw new TamiranApiException('پرونده بسته است.',409);if($scope['role']==='technician'&&(int)$case['primary_technician_user_id']!==(int)$scope['actor']['id'])throw new TamiranApiException('فقط تکنسین مسئول پرونده می‌تواند درخواست قطعه ثبت کند.',403);
    $item=$pdo->prepare('SELECT id,public_id,title FROM repair_inventory_items WHERE id=:id AND shop_id=:shop AND is_active=1 LIMIT 1');$item->execute(['id'=>$itemId,'shop'=>$scope['shop_id']]);$itemRow=$item->fetch();if(!is_array($itemRow))throw new TamiranApiException('کالای فعال پیدا نشد.',404);
    $public=tamiran_id();$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO repair_part_requests(public_id,shop_id,branch_id,case_id,item_id,requested_by_user_id,quantity,status,notes) VALUES(:public,:shop,:branch,:case,:item,:actor,:quantity,'pending',:notes)")->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'case'=>$caseId,'item'=>$itemId,'actor'=>$scope['actor']['id'],'quantity'=>$quantity,'notes'=>v2_text($input['notes']??'','توضیحات',2000,false)]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'part_request.create','repair_part_request',$public,null,['case'=>$case['case_public_id'],'item'=>$itemRow['public_id'],'quantity'=>$quantity]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}
    if(in_array($case['process_status'],['diagnosing','estimate_pending','awaiting_customer_approval','repairing'],true))v2_transition($pdo,$scope,$caseId,'awaiting_parts','درخواست قطعه ثبت شد و پرونده خودکار در انتظار قطعه قرار گرفت',(int)$case['lock_version'],'part-request:'.$public.':route',true);
    return ['created'=>true,'publicId'=>$public];
}

function inventory_v2_reserve(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.reserve',['warehouse_keeper'],'رزرو فقط برای انباردار یا مدیر مجاز است.');$requestId=(int)($input['requestId']??0);$quantity=(int)($input['quantity']??0);if($quantity<1)throw new TamiranApiException('تعداد رزرو معتبر نیست.');
    $pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT r.*,i.public_id AS item_public_id FROM repair_part_requests r INNER JOIN repair_inventory_items i ON i.id=r.item_id WHERE r.id=:id AND r.shop_id=:shop AND r.branch_id=:branch AND r.status IN ('pending','needs_supply','reserved','partially_delivered') FOR UPDATE");$statement->execute(['id'=>$requestId,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$request=$statement->fetch();if(!is_array($request))throw new TamiranApiException('درخواست قابل رزرو نیست.',409);$remaining=(int)$request['quantity']-(int)$request['reserved_quantity'];if($remaining<1||$quantity>$remaining)throw new TamiranApiException('تعداد رزرو بیشتر از مانده درخواست است.',409);$warehouseId=(int)($input['warehouseId']??0);$stock=v2_stock_mutate($pdo,$scope,$warehouseId,(int)$request['item_id'],0,$quantity,'reserve','part_request',$request['public_id'],v2_text($input['reason']??'رزرو درخواست قطعه','علت',1000),(int)$request['case_id']);$newReserved=(int)$request['reserved_quantity']+$quantity;$newStatus=(int)$request['delivered_quantity']>0?'partially_delivered':'reserved';$pdo->prepare('UPDATE repair_part_requests SET reserved_quantity=:quantity,status=:status,source_type=\'branch_stock\',reservation_expires_at=:expires,reservation_expired_at=NULL WHERE id=:id')->execute(['quantity'=>$newReserved,'status'=>$newStatus,'expires'=>$input['expiresAt']??date('Y-m-d H:i:s',time()+48*3600),'id'=>$requestId]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'inventory.reserve','repair_part_request',$request['public_id'],['reserved'=>(int)$request['reserved_quantity']],['reserved'=>$newReserved,'status'=>$newStatus,'stock'=>$stock]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return ['reserved'=>true,'stock'=>$stock];
}

function inventory_v2_issue(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.issue',['warehouse_keeper'],'تحویل قطعه فقط برای انباردار یا مدیر مجاز است.');$requestId=(int)($input['requestId']??0);$quantity=(int)($input['quantity']??0);$technicianId=(int)($input['technicianUserId']??0);$idempotency=v2_text($input['idempotencyKey']??'','شناسه یکتای تحویل قطعه',160);if($quantity<1)throw new TamiranApiException('تعداد تحویل معتبر نیست.');
    $replay=$pdo->prepare('SELECT public_id FROM repair_part_issues WHERE shop_id=:shop AND idempotency_key=:idempotency LIMIT 1');$replay->execute(['shop'=>$scope['shop_id'],'idempotency'=>$idempotency]);$replayed=$replay->fetchColumn();if(is_string($replayed))return['issued'=>true,'replayed'=>true,'issuePublicId'=>$replayed];
    $pdo->beginTransaction();try{$insideReplay=$pdo->prepare('SELECT public_id FROM repair_part_issues WHERE shop_id=:shop AND idempotency_key=:idempotency LIMIT 1 FOR UPDATE');$insideReplay->execute(['shop'=>$scope['shop_id'],'idempotency'=>$idempotency]);$insidePublic=$insideReplay->fetchColumn();if(is_string($insidePublic)){$pdo->commit();return['issued'=>true,'replayed'=>true,'issuePublicId'=>$insidePublic];}$statement=$pdo->prepare("SELECT r.*,c.public_id AS case_public_id FROM repair_part_requests r INNER JOIN repair_cases c ON c.id=r.case_id WHERE r.id=:id AND r.shop_id=:shop AND r.branch_id=:branch AND r.status IN ('reserved','partially_delivered') FOR UPDATE");$statement->execute(['id'=>$requestId,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$request=$statement->fetch();if(!is_array($request))throw new TamiranApiException('درخواست قابل تحویل نیست.',409);$availableReserved=(int)$request['reserved_quantity']-(int)$request['delivered_quantity'];if($quantity>$availableReserved)throw new TamiranApiException('تعداد تحویل از رزرو باقی‌مانده بیشتر است.',409);$case=v2_case($pdo,$scope,(int)$request['case_id']);if($technicianId<1)$technicianId=(int)$case['primary_technician_user_id'];if($technicianId<1)throw new TamiranApiException('تکنسین تحویل‌گیرنده مشخص نیست.',409);$warehouseId=(int)($input['warehouseId']??0);$stock=v2_stock_mutate($pdo,$scope,$warehouseId,(int)$request['item_id'],-$quantity,-$quantity,'issue','part_request',$request['public_id'],v2_text($input['reason']??'تحویل قطعه به تکنسین','علت',1000),(int)$request['case_id']);$issuePublic=tamiran_id();$pdo->prepare("INSERT INTO repair_part_issues(public_id,shop_id,branch_id,part_request_id,case_id,item_id,technician_user_id,quantity,status,issued_by_user_id,idempotency_key,notes) VALUES(:public,:shop,:branch,:request,:case,:item,:technician,:quantity,'awaiting_technician',:actor,:idempotency,:notes)")->execute(['public'=>$issuePublic,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'request'=>$requestId,'case'=>$request['case_id'],'item'=>$request['item_id'],'technician'=>$technicianId,'quantity'=>$quantity,'actor'=>$scope['actor']['id'],'idempotency'=>$idempotency,'notes'=>v2_text($input['notes']??'','توضیحات',2000,false)]);$delivered=(int)$request['delivered_quantity']+$quantity;$status=$delivered<(int)$request['quantity']?'partially_delivered':'delivered';$pdo->prepare('UPDATE repair_part_requests SET delivered_quantity=:delivered,status=:status WHERE id=:id')->execute(['delivered'=>$delivered,'status'=>$status,'id'=>$requestId]);v2_notify($pdo,$scope,$technicianId,'part_issued','قطعه آماده تأیید دریافت است','درخواست '.$request['public_id'],'repair_part_issue',$issuePublic);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'inventory.issue','repair_part_issue',$issuePublic,null,['quantity'=>$quantity,'technician'=>$technicianId,'stock'=>$stock,'idempotencyKey'=>$idempotency]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return ['issued'=>true,'replayed'=>false,'issuePublicId'=>$issuePublic,'stock'=>$stock];
}

function inventory_v2_finalize_issue(PDO $pdo,array $scope,array $input):array
{
    $public=v2_text($input['issuePublicId']??'','تحویل قطعه',80);$decision=(string)($input['decision']??'');if(!in_array($decision,['consumed','returned'],true))throw new TamiranApiException('نتیجه قطعه باید مصرف یا مرجوع باشد.');
    $pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT x.*,r.public_id AS request_public_id,r.quantity AS requested_quantity,r.consumed_quantity,r.returned_quantity,r.delivered_quantity,i.hot_return_required FROM repair_part_issues x INNER JOIN repair_part_requests r ON r.id=x.part_request_id INNER JOIN repair_inventory_items i ON i.id=x.item_id WHERE x.public_id=:public AND x.shop_id=:shop AND x.branch_id=:branch FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$issue=$statement->fetch();if(is_array($issue)&&in_array($issue['status'],['consumed','returned'],true)){if($issue['status']!==$decision)throw new TamiranApiException('این تحویل قبلاً با نتیجه دیگری نهایی شده است.',409);$pdo->commit();$routed=inventory_v2_route_after_parts($pdo,$scope,(int)$issue['case_id'],'part-finalize:'.$public);return['finalized'=>true,'replayed'=>true,'decision'=>$decision,'routed'=>$routed];}if(!is_array($issue)||!in_array($issue['status'],['awaiting_technician','delivered'],true))throw new TamiranApiException('تحویل قطعه قابل نهایی‌سازی نیست.',409);if($scope['role']!=='repair_manager'&&(int)$issue['technician_user_id']!==(int)$scope['actor']['id'])throw new TamiranApiException('فقط تکنسین تحویل‌گیرنده می‌تواند قطعه را نهایی کند.',403);$warehouse=$pdo->prepare('SELECT id FROM repair_warehouses WHERE shop_id=:shop AND branch_id=:branch AND is_main=1 AND is_active=1 LIMIT 1');$warehouse->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$warehouseId=(int)$warehouse->fetchColumn();if($warehouseId<1)throw new TamiranApiException('انبار اصلی شعبه پیدا نشد.',409);$quantity=(int)$issue['quantity'];$pdo->prepare('UPDATE repair_part_issues SET status=:status,technician_confirmed_at=COALESCE(technician_confirmed_at,NOW()),finalized_at=NOW(),notes=COALESCE(:notes,notes) WHERE id=:id')->execute(['status'=>$decision,'notes'=>v2_text($input['notes']??'','توضیحات',2000,false),'id'=>$issue['id']]);$consumed=(int)$issue['consumed_quantity']+($decision==='consumed'?$quantity:0);$returned=(int)$issue['returned_quantity']+($decision==='returned'?$quantity:0);$finalized=$consumed+$returned;$requestStatus=$finalized>=(int)$issue['delivered_quantity']&&$finalized>=(int)$issue['requested_quantity']?($consumed>0?'consumed':'returned'):'partially_delivered';$pdo->prepare('UPDATE repair_part_requests SET consumed_quantity=:consumed,returned_quantity=:returned,status=:status WHERE id=:id')->execute(['consumed'=>$consumed,'returned'=>$returned,'status'=>$requestStatus,'id'=>$issue['part_request_id']]);if($decision==='returned'){v2_stock_mutate($pdo,$scope,$warehouseId,(int)$issue['item_id'],$quantity,0,'return','part_issue',$public,v2_text($input['reason']??'مرجوعی قطعه از تکنسین','علت',1000),(int)$issue['case_id']);}else{v2_stock_mutate($pdo,$scope,$warehouseId,(int)$issue['item_id'],0,0,'consume','part_issue',$public,v2_text($input['reason']??'مصرف قطعه در تعمیر','علت',1000),(int)$issue['case_id']);if((bool)$issue['hot_return_required']){$pdo->prepare("INSERT INTO repair_hot_returns(public_id,shop_id,branch_id,case_id,item_id,technician_user_id,quantity,status,notes) VALUES(:public,:shop,:branch,:case,:item,:technician,:quantity,'pending_return',:notes)")->execute(['public'=>tamiran_id(),'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'case'=>$issue['case_id'],'item'=>$issue['item_id'],'technician'=>$issue['technician_user_id'],'quantity'=>$quantity,'notes'=>'تعهد داغی خودکار از مصرف قطعه']);}}tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'part_issue.finalize','repair_part_issue',$public,['status'=>$issue['status']],['status'=>$decision,'quantity'=>$quantity],v2_text($input['reason']??'تعیین تکلیف قطعه','علت',1000));$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}$routed=inventory_v2_route_after_parts($pdo,$scope,(int)$issue['case_id'],'part-finalize:'.$public);return ['finalized'=>true,'replayed'=>false,'decision'=>$decision,'routed'=>$routed];
}

function inventory_v2_reject_or_cancel(PDO $pdo,array $scope,array $input,string $action):array
{
    v2_require_permission($scope,'inventory.request.decide',['warehouse_keeper','technician'],'رد یا لغو درخواست مجاز نیست.');if($action==='reject'&&$scope['role']==='technician')throw new TamiranApiException('تکنسین نمی‌تواند درخواست را رد کند.',403);$requestId=(int)($input['requestId']??0);$reason=v2_text($input['reason']??'','علت',1000);$pdo->beginTransaction();try{$statement=$pdo->prepare('SELECT * FROM repair_part_requests WHERE id=:id AND shop_id=:shop AND branch_id=:branch FOR UPDATE');$statement->execute(['id'=>$requestId,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$request=$statement->fetch();if(!is_array($request)||in_array($request['status'],['consumed','returned','rejected','cancelled'],true))throw new TamiranApiException('درخواست قابل تغییر نیست.',409);if($scope['role']==='technician'&&(int)$request['requested_by_user_id']!==(int)$scope['actor']['id'])throw new TamiranApiException('فقط درخواست‌کننده می‌تواند درخواست خودش را لغو کند.',403);$openIssues=$pdo->prepare("SELECT COUNT(*) FROM repair_part_issues WHERE part_request_id=:request AND status NOT IN ('consumed','returned')");$openIssues->execute(['request'=>$requestId]);if((int)$openIssues->fetchColumn()>0)throw new TamiranApiException('ابتدا تمام قطعات تحویل‌شده را مصرف یا مرجوع کنید.',409);$reserved=max(0,(int)$request['reserved_quantity']-(int)$request['delivered_quantity']);if($reserved>0){$warehouseId=(int)($input['warehouseId']??0);v2_stock_mutate($pdo,$scope,$warehouseId,(int)$request['item_id'],0,-$reserved,'release','part_request',$request['public_id'],$reason,(int)$request['case_id']);}$status=$action==='reject'?'rejected':'cancelled';$pdo->prepare('UPDATE repair_part_requests SET status=:status,rejection_reason=:reason,reserved_quantity=delivered_quantity WHERE id=:id')->execute(['status'=>$status,'reason'=>$reason,'id'=>$requestId]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'part_request.'.$status,'repair_part_request',$request['public_id'],['status'=>$request['status'],'reserved'=>(int)$request['reserved_quantity']],['status'=>$status,'released'=>$reserved],$reason);v2_notify($pdo,$scope,(int)$request['requested_by_user_id'],'part_request_'.$status,'درخواست قطعه تعیین‌تکلیف شد',$reason,'repair_part_request',$request['public_id']);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}$routed=inventory_v2_route_after_parts($pdo,$scope,(int)$request['case_id'],'part-request:'.$request['public_id'].':'.$status);return ['updated'=>true,'status'=>$status,'routed'=>$routed];
}

tamiran_api(static function():array{$pdo=tamiran_db();$scope=v2_scope();v2_require_capability(v2_product_policy($pdo,$scope),'inventoryEnabled','انبار برای محصول یا تنظیمات این تعمیرگاه فعال نیست.');$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET')return inventory_v2_payload($pdo,$scope);if($method!=='POST')throw new TamiranApiException('روش درخواست مجاز نیست.',405);tamiran_require_csrf();$input=tamiran_json_body();return match((string)($input['action']??'')){
    'request'=>inventory_v2_request($pdo,$scope,$input),'reserve'=>inventory_v2_reserve($pdo,$scope,$input),'issue'=>inventory_v2_issue($pdo,$scope,$input),'finalize_issue'=>inventory_v2_finalize_issue($pdo,$scope,$input),'reject'=>inventory_v2_reject_or_cancel($pdo,$scope,$input,'reject'),'cancel'=>inventory_v2_reject_or_cancel($pdo,$scope,$input,'cancel'),default=>throw new TamiranApiException('عملیات انبار معتبر نیست.'),};});
